package ps.lambda.patterns.factory;import ps.lambda.patterns.factory.factory.Factory;import ps.lambda.patterns.factory.model.Rectangle;import ps.lambda.patterns.factory.registry.SwitchRegistry;public class PlayWithSwitchRegistry {		@SuppressWarnings("unchecked")	public static void main(String[] args) {		SwitchRegistry registry = new SwitchRegistry();				Factory<Rectangle> rectangleFactory =				(Factory<Rectangle>)registry.buildShapeFactory("rectangle");		System.out.println("Rectangle : " + rectangleFactory.newInstance());	}}